import{_ as l,a as i,b as r,c as a}from"./chunks/fa48014c2b84cebecc6d.uaLbKMth.js";import{_ as o,C as n,o as s,c as m,j as e,a as h,E as d,a6 as u}from"./chunks/framework.CnPv4DE1.js";const P=JSON.parse('{"title":"心流状态：把你的生活变成一款令人上瘾的电子游戏","description":"","frontmatter":{"title":"心流状态：把你的生活变成一款令人上瘾的电子游戏","originalTitle":"The Flow State: Turn Your Life Into An Addictive Video Game","date":"2024-06-22","originalUrl":"https://thedankoe.com/letters/the-flow-state-turn-life-into-an-addictive-video-game/","minutes":36,"sourceHash":"2c61b8b81e3a0890d501497658d0e497ed5b75758bc1a4a823f7732690682c8d","translation":"AI-assisted, block-aligned; not official","head":[["link",{"rel":"canonical","href":"https://thedankoe.com/letters/the-flow-state-turn-life-into-an-addictive-video-game/"}]]},"headers":[],"relativePath":"letters/the-flow-state-turn-life-into-an-addictive-video-game.md","filePath":"letters/the-flow-state-turn-life-into-an-addictive-video-game.md"}'),c={name:"letters/the-flow-state-turn-life-into-an-addictive-video-game.md"};function g(f,p,b,k,_,v){const t=n("ArticleMeta");return s(),m("div",null,[p[0]||(p[0]=e("h1",{id:"心流状态-把你的生活变成一款令人上瘾的电子游戏",tabindex:"-1"},[h("心流状态：把你的生活变成一款令人上瘾的电子游戏 "),e("a",{class:"header-anchor",href:"#心流状态-把你的生活变成一款令人上瘾的电子游戏","aria-label":'Permalink to "心流状态：把你的生活变成一款令人上瘾的电子游戏"'},"​")],-1)),d(t),p[1]||(p[1]=u('<p><a href="https://www.youtube.com/embed/hN-ITerTpLg?si=_zWJMJHDl6h6D_8R" target="_blank" rel="noreferrer">观看原文视频</a></p><p>让我问你一个问题：</p><p><em>你是否曾体验过人类的最佳体验？</em></p><p>那种被职业运动员、精神导师和改变文化的艺术家们认定为他们成功关键的意识状态。</p><p>你以前曾感受到过它。</p><ul><li>那种牢不可破的自信感。</li><li>感觉脚步轻盈，对未来充满安全感。</li><li>技能升华为艺术，你不再在乎别人怎么想的那一刻。</li><li>你感觉自己仿佛不存在，而且想不出任何其他你想做的事情。</li></ul><p>这被称为心流（flow）状态。</p><p>一种巅峰体验、极度享受和毫不费力就能保持高效的状态。</p><p>它与“活在当下”非常相似。你知道的，就是那些精神导师们整天挂在嘴边说教的东西。</p><p>活在当下源于一种开放的专注状态。你将大脑从对任何特定想法的依附中解放出来，与生活本身融为一体。</p><p>另一方面，当你在追求一个崇高目标时，心流就会派上用场。你与眼前的任务融为一体，从而实现一个有意义的目标。</p><p><em>确切地说，是一个自我生成的目标。</em></p><p>而不是一个指派给你的、主宰你命运并将你的身份塑造成一个无意识怪物的目标。</p><p>畅销书《心流》（Flow）的作者、心流心理学教父米哈里·契克森米哈赖（Mihaly Csikszentmihalyi）将心流描述为一种“自得其乐的活动（autotelic activity）”：</p><blockquote><p>“Autotelic”一词源于两个希腊单词，auto 意为<em>自我</em>，telos 意为<em>目标</em>。它指的是一种自给自足的活动，做这件事不是期望某种未来的利益，而仅仅是因为做这件事本身就是一种奖赏。</p></blockquote><p>在这篇文章中，我们将大量引用契克森米哈赖——以及人类表现领域的顶尖专家史蒂芬·科特勒（Steven Kotler）——的著作。</p><p>当今社会的一大问题似乎是我们无法单纯地把工作完成。</p><p>我们在职业生涯中缺乏意义感。</p><p>任务重复且没完没了。</p><p>干扰无处不在。</p><p>我们不清楚自己想从生活中得到什么。</p><p>正是因为这个原因，多巴胺最近成了一个相当热门的话题。多巴胺在进入心流状态中起着至关重要的作用，但它的作用远不止于此。</p><p>太多人陷入了目光短浅、流于表面的生活状态。他们只知道去上学、找工作、刷手机、追求物质，却从未体验过生活所能提供的深度。</p><p>那根本不叫生活。</p><p>但是，如果我告诉你，你可以在生活中那些无聊、平凡甚至糟糕的方面找到乐趣呢？</p><p>更进一步，如果我告诉你，你可以利用心流状态在 6 个月内，而不是 6 年内，实现你一直拖延的那些有意义的目标呢？</p><p>理解心流的结果，是发现你一生的事业，对那份事业充满热情，并掌握工具去驾驭那些导致大多数人陷入混乱的可怕焦虑与压倒感。</p><p>生活的乐趣并非由随机性或运气决定的。它是通过将生活解构为一场游戏并学习如何去玩而<em>创造</em>出来的。</p><h2 id="电子游戏的解剖学——为什么我们会沉迷其中" tabindex="-1">电子游戏的解剖学——为什么我们会沉迷其中 <a class="header-anchor" href="#电子游戏的解剖学——为什么我们会沉迷其中" aria-label="Permalink to &quot;电子游戏的解剖学——为什么我们会沉迷其中&quot;">​</a></h2><p>我曾经玩过一款游戏，它消耗了我生命中太多的时间。</p><p>它叫《魔兽世界》（World Of Warcraft）。</p><p>如果你对它很熟悉，不客气，就当是给你带来一波怀旧之情了。</p><p>对于那些不熟悉的人，魔兽世界（WoW）是一款 MMORPG。一款大型多人在线角色扮演游戏。我经常觉得它比现实世界更有趣。</p><p>在夏天的夜晚，做完救生员的兼职回家后，我会戴上耳机，沉浸在那个在线世界里。<em>除了我的心智和那些让它保持理智的代码行之外，其他一切都不重要。</em></p><p>当你作为新手登录时，你会面临一系列任务。</p><p>首先，你选择一个阵营，然后是种族，接着是职业，并定制你角色的外观。游戏有两个阵营，联盟（Alliance）和部落（Horde）。许多玩家对自己选择的阵营充满热情，甚至带有一种意识形态。我玩的是联盟，但我总觉得这种数字宗教有点过了，所以我并没有真的“恨”另一方……我只是觉得那些角色看起来有点滑稽。</p><p>我的角色大部分不是人类就是暗夜精灵，但你可以选择从侏儒、兽人、熊猫人（Pandaren）到亡灵的任何种族。你选择的“职业”决定了你在整个游戏中的主要行动。职业就是你的角色定位和游玩风格。</p><p>你可以扮演坦克、治疗或输出（伤害）的角色。当你和其他人一起完成任务、地下城或团队副本时，坦克负责让敌人攻击自己，治疗负责让团队活下来，而输出角色——无论是持刀剑近战还是用魔法远程——嗯……他们负责对敌人造成伤害。</p><p>电子游戏酷的一点在于，你可以尝试扮演各种角色，如果不喜欢，还可以重头来过。</p><p>你是否注意到了现实世界中的规律？你的身份如何影响你的机会和潜力？如何依附于某一种政治、宗教或社会意识形态，会让你难以达到最大乐趣的状态？我们很快就会剖析这背后的心理学。</p><p>创建角色后，你会被扔进那个种族专属的新手村——就像你成长环境中的文化一样。你所知道的只有地图上的一个小点。其余部分都是黑暗和未知的。在现实中，你在一种决定了你信仰的文化中长大，你把这些信仰当成真理接受下来。你没有意识到的是，你只了解不到 1% 的现实（如果我真要给个数字的话，它应该更接近 .000001%，但我们总是喜欢表现得好像我们知道的比实际多，这反而害了我们自己）。</p><p>除非你获得了技能和能力，升级到足以在那些区域生存的程度，否则游戏不会让你进入地图的新区域。</p><p>随着你的升级，你解锁了新的任务、地下城、特殊能力、职业选择，以及骑马或飞行到世界新区域的能力。</p><p>你不需要了解更多细节，但这将帮助我们回答几个问题：</p><ul><li>为什么我们会觉得电子游戏如此有趣，甚至到了上瘾的地步？</li><li>是否有可能复制这种乐趣，在追求我们自己的人生目标时取得进展？</li><li>我们能否像电子游戏一样构建我们的生活，让我们如此沉浸其中，以至于忘记了我们一开始其实是在玩一场游戏？</li></ul><p>让我们解构这款奇幻游戏的各个部分，以了解让我们的头脑上瘾的原则。</p><h3 id="目标的层级结构——头脑清晰的关键" tabindex="-1">目标的层级结构——头脑清晰的关键 <a class="header-anchor" href="#目标的层级结构——头脑清晰的关键" aria-label="Permalink to &quot;目标的层级结构——头脑清晰的关键&quot;">​</a></h3><p>大脑渴望秩序。</p><p>电子游戏有任务、升级和技能发展，从而让你的大脑聚焦于手头的大目标，并消除干扰。</p><p>电子游戏的设计初衷是为了让最佳体验更容易实现：</p><blockquote><p>它们有需要学习技能的规则，它们设定目标，提供反馈，并让掌控成为可能。它们通过使活动尽可能地有别于日常存在中所谓的“至高现实（paramount reality）”，来促进专注和投入。——《心流》</p></blockquote><p>这里的关键词是“设计初衷（designed）”。</p><p>在阅读这封信时，我想让你在脑海深处保留一个问题：“我如何才能<em>设计</em>出让我对生活拥有掌控感的一生、一个月、一周和一天？”</p><p>就像电子游戏中引导你进入任务的教程阶段一样，社会也是以类似的方式设计的：</p><ul><li>你去上学是为了搞懂社会想让你玩的这场游戏。</li><li>一个目标的层级结构被摆在你面前。去上学、找工作、赞美你的上帝。</li><li>起初，有充足的挑战让你的头脑保持聚焦，但很快，生活变得重复和乏味。</li></ul><p>人的天性是被那些给我们带来舒适和安全感的事物所吸引，但这很快就会反噬我们。</p><p>人生的默认路径存在的一个巨大问题是<em>一刀切并不适用所有人。</em></p><p>不难看出，大多数人并不享受他们的生活。他们被困在自己讨厌的工作中。他们失去了对他们赞美的上帝的信任。他们被指派去实现目标——比如在学校读一本特定的书——这让他们对学习倒了胃口，所以他们就不学了。</p><p><em>我们都在不同的事物中找到乐趣。</em></p><p>而且，我们从中找到乐趣的事物会随着我们身份的发展而演变。</p><p>100 级的玩家不会在 1 级的挑战中找到乐趣。</p><p>1 级的玩家也不会理解 100 级的挑战。</p><p>享受生活的关键在于，保持一种感觉，即自己的技能足以应对任何自己所理解的情境中的挑战。你必须创造一个带有规则系统的环境，这样你就能知道自己做得有多好。如此一来，注意力就会变得极其集中，以至于没有剩余的精力去思考任何无关的事情或担心问题。</p><p>到目前为止，我们学到的教训是，电子游戏让你如此深地沉浸在虚构的现实中，以至于它变成了你的现实。除了该游戏的规则和结构之外，没有任何东西占据你的注意力。你达到了绝对的清醒。在你的意识中存在零干扰。</p><p>这强调了你所选择的目标的重要性。</p><ul><li>一个宏大的人生目标，用来框定你认为重要的信息。</li><li>一系列反向推导的目标，为你的行动带来清晰度。</li><li>一个当下的微小目标，用来吸引你的注意力并促使你进入心流（flow）。</li></ul><p>这就是为什么那些古怪的深度工作（deep work）技巧——比如播放纯器乐、前一晚规划好第二天、以及工作时戴帽子——会如此有效。它们将你的精神能量从干扰中转移，集中起来。</p><p>大脑是一部机器，辅助你实现已知目标和发现未知目标。</p><p>你的大脑会注意、接受或拒绝，并利用信息来达成你喂给它的目标。如果你总是专注于负面的结果，你的生活就会变得负面。如果你只专注于社会指派给你的目标，你就会失去对生活的掌控感。</p><p>在心理学中，这被称为模式识别。当你注意到有助于你实现意识或潜意识目标的信息时，你会<em>感觉</em>到多巴胺的分泌。你情不自禁地会利用这些信息来取得进展。</p><p>问题是，我们如何利用关于目标的这一知识来过上更有意义的生活？</p><p>如果你想改变你的生活，你必须首先将自己从那些让生活变得毫无乐趣的重复性任务链中抽离出来。你必须潜入未知之中。</p><p>顺便说一句，在我的书《专注的艺术》（<a href="https://theartoffocusbook.com/" target="_blank" rel="noreferrer">The Art Of Focus</a>）中，我会帮你制定你自己的人生规划。</p><h3 id="未知——无限潜力的乐土" tabindex="-1">未知——无限潜力的乐土 <a class="header-anchor" href="#未知——无限潜力的乐土" aria-label="Permalink to &quot;未知——无限潜力的乐土&quot;">​</a></h3><p>想象一下，你不会游泳。</p><p>如果我邀请你乘坐直升机在海面上观光，你会有什么感觉？</p><p>你可能会有点害怕，但如果不接受，那你就太傻了。</p><p>那么，如果在那趟飞行中，我把直升机降到水面上，把你推出去，然后再把直升机拉高一点点，迫使你必须游泳，你又会作何感想？</p><p>接下来可能会发生几件事：</p><ul><li>你会屈服于恐惧，过度思考，然后溺水。</li><li>你会像疯子一样扑腾，想尽一切办法浮在水面上，但很快就会耗尽体力，结果再次……溺水。</li><li>你会保持冷静，尝试漂浮，并可能在水面上待得足够久，以制定出计划。</li></ul><p><em>这些都不是最佳选择。</em></p><p>当你玩电子游戏时，你拥有一张数字世界的地图。</p><p>在那张地图上，有一些未知区域。那些你尚未或无法探索的地方。</p><p>你不能直接传送到这些区域的中心是有原因的。你很可能会被比你高50级的怪物包围，然后被一击秒杀。</p><p><em>那好玩吗？</em></p><p>你还会想继续玩这个游戏吗？</p><p>那么，如果你一直完成任务，直到解锁了飞行能力呢？如果达到了可以打你第一个副本的等级呢？</p><p>你会狂喜！你不会浪费任何时间。你会以最快的速度赶到那里，测试你的能力。在现实世界中，你甚至可能会熬个通宵，因为你沉迷于看到向你敞开的新机遇。</p><p><strong>这里的教训是：</strong></p><p><em>意义就在你能力的边缘地带。</em></p><p>未知世界的边缘。</p><p>不深到让你陷入混乱，也不浅到让你将自己封闭在深度之外。</p><p>这是一个绝佳的平衡点，你的技能足以应对任何特定情况下的挑战。</p><p><img src="'+l+'" alt=""></p><p>你以前经历过这种状态……</p><p>当你毫无来由地感觉棒极了时。当你知道到底该做什么来让生活取得进展时。当你脑洞大开、灵感源源不断时。当你对未来的愿景如此清晰，以至于你忍不住要付诸行动时。</p><p>意识的“心流”状态是信息“流动”最大化的地方。所有的想法、灵感和精神能量对你试图实现的有意义的目标层级来说，都是<em>有用的</em>。</p><p>信号最大化，噪音最小化。</p><p>专注最大化，分心最小化。</p><p>这才是真正的教育。学习、实践和探索同步进行。而不是被告知要学什么，去完成一项你根本不在乎的任务，走在一条成群结队的人走过的老路上。</p><p>这给了我们一个提示，告诉我们如何最大限度地延长处于心流状态的时间。</p><p>我喜欢把头脑看作是体验的代谢系统。</p><p>吃得太多，你会感到迟钝。</p><p>吃得太少，你会感到焦躁。</p><p>当你被信息淹没时，你会感到焦虑。</p><p>当你吸收的信息太少时，你会感到无聊。</p><p>作为人类，我们贪多嚼不烂的情况并不罕见。当你已经水漫过脖子时，还接下更多的工作。学了太多的东西，却指望自己不被压垮。明明知道该说“不”，却为了不让别人失望而说了“好”。</p><p>最佳的心理状态是，你能够顺其自然地消化生活。你不假思索地学习和行动，并脱胎换骨成为一个全新的人。</p><p>你的技能足以匹配情况的挑战。没有任何摩擦。你顺应着生活抛给你的信息而流动。</p><p>人们经常说他们不记得处于心流中的时光，但一旦脱离那种状态，他们就觉得仿佛解锁了自我发展的新层次。</p><p>关于心流状态的一个常见误解是：</p><p>它不是努力尝试的产物。</p><p>它是毫不费力的。</p><blockquote><p>我一直对逆向努力法则着迷。有时我称之为“逆向法则”。当你试图浮在水面上时，你会下沉；但当你试图下沉时，你反而会漂浮。当你屏住呼吸时，你就会失去呼吸——这立刻让人想起一句古老且常被忽视的名言：“凡想保全自己灵魂的，必丧掉灵魂。”——阿兰·瓦茨（Alan Watts）</p></blockquote><p>现在，这很明显，但你不可能一蹴而就，从做着你讨厌的朝九晚五的工作，变成靠毕生事业赚取几百万。</p><p>但是，你可以在生活中创造并遵循一条任务线，去达成任何你想要的目标——无论是减肥、变好看、提升魅力、赚更多钱，还是从事你喜欢的工作。</p><p>唯一挡在路上的只有<em>你</em>。</p><h3 id="角色创建——发挥你的潜力" tabindex="-1">角色创建——发挥你的潜力 <a class="header-anchor" href="#角色创建——发挥你的潜力" aria-label="Permalink to &quot;角色创建——发挥你的潜力&quot;">​</a></h3><blockquote><p>在我们历史的这个阶段，一个人应该有可能建立一个并非仅仅是生物驱动和文化习惯产物的自我，而是一个有意识的、个性化的创造物。——《进化的自我》（<em>The Evolving Self</em>）</p></blockquote><p>你没有达到你想要的状态，是因为：</p><ul><li>你没有做出能导向一份有目标感的事业的选择。</li><li>你没有做出能导向美满关系的选择。</li><li>你没有做出能导向健康和形体美的选择。</li></ul><p>现在的你，正是你过去选择的具象体现。</p><p>所以，如果你想掌控自己将成为什么样的人，你的选择就至关重要。</p><p>这里有两点：</p><ol><li>你想成为谁——视角与拉远视野。</li><li>能带你到达那里的选择——感知与拉近视野。</li></ol><p>美好的生活，是通过不断提醒自己你的愿景，并通过一致的行动去重塑能够将其变现的身份而创造出来的。</p><p>你知道<em>你</em>是谁吗？</p><p>你的身份。你的自我概念。你的性格。</p><p>你在人生这场游戏中一直扮演的那个小角色。一张塑造你视角的思想网。一个塑造你对各种情况感知的视角。一种决定你做出何种选择的感知。你的选择造就了你是谁，以及你所过的生活品质。</p><p><em>在相对的现实中，你是一个视角的载体。</em></p><p>你的视角可以扩展，也可以收缩。</p><p>要么全神贯注于某项任务，要么与生活融为一体。</p><p>要么被情绪粗暴摆布，要么淹没在全是熟悉的未来事件的汪洋中。</p><p>在电子游戏中，你要创建你的角色。</p><p>法师只能穿布甲，施展特定的一套法术。他们不能单独与大型怪物战斗，因为他们不够强壮。</p><p>战士穿戴护甲进行近战。他们能承受更多伤害，并能单挑更多怪物，但这也伴随着劣势。他们并不专精于某些职业技能，所以在市场上，他们无法像法师那样赚取那么多金币。</p><p>你在游戏中所选的职业、专业、任务和路线，决定了你未来能做什么。</p><p><em>换句话说，如果你不喜欢自己的生活，那是因为你的身份让你无法去注意到并追求那些让你感到愉悦的挑战。</em></p><p>出生的那天起，你就变成了一块学习的海绵。你的生物学目标是生存，所以你从环境中汲取信息来实现这个目标。</p><ul><li>你学会了你所说的语言。</li><li>你学会了爬行、走路和奔跑。</li><li>有人教你“眼睛、耳朵、嘴巴和鼻子”，因为你无法直接看到自己的脸。</li><li>你的父母、老师、朋友、书籍和媒体告诉你什么是好的、什么是坏的，于是你的大脑转变为只保留那些能让你按照这些标准生存下来的信息。</li></ul><p>从结构的角度来看，世界观或视角是由目标，以及这些目标让你意识到的问题所组成的。</p><p>只有这样，你才能选择解决这些问题、实现目标，并为下一个目标腾出空间。</p><p>每一天，拉远视野，提醒自己你不想要什么。你不需要去专注你想要什么，因为那会通过你的选择自然显现出来。</p><p>把这个框架置于你大脑的最优先位置。</p><p>不要让任何干扰穿透它。</p><p>每当面临选择时，拉远视野，然后对齐这个框架。</p><p>“这对我正在努力创造的未来有好处吗？”</p><p>然后，果断一点。做出决定。</p><p>允许失败进入你的生活，这样你才能在下一次纠正自己的行为。</p><p>觉察即是一剂良药。</p><p>但是，如果你没有愿景，你可能会接受社会分配给你的任务，这几乎总是会导致你无法掌控自己追求的目标或解决的问题的层级。换言之，你——作为一个视角——停止了成长。在25到35岁左右，你会遇到一个无法逃避的责任气泡，将你困在一团混乱和无意义的迷雾中。</p><p>如果你自我认同为一名“聪明”的学生，你的目标就是申请大学，而你唯一注意到的问题，就是那些你必须为此复习备考的州级统考之类的考试。</p><p>因此，你把精力投入到那个目标上。</p><p>当你实现它时，你的心灵获得了奖励，于是你继续沿着这条狭窄的道路前行。</p><p>问题在于，这条路是已知的。它是别人指派给你的。在此之前，人们已经走过很多次了。你很清楚，走这条路，你的成就就会受限于其他人曾经达到的结果，但你不在乎，因为这就是你被设定好要做的事。</p><p>稍后，我们将讨论另一种驶向未知的载体。一种能让你在<em>你所创造的</em>道路上做出选择并找到清晰方向的载体。</p><p>一种能让你接触到你独特潜能的载体。</p><p>一条无人走过的路。</p><p><em>你的毕生事业。</em></p><p>你的视角——目标和问题——框定了你可以获取的任何及所有信息和机会。说到信息，我指的不是书本、播客或文字。我指的是你感知到的任何事物。声音、景象、气味、味道和触觉。它们的组合构成了我们意识的内容。构成了我们的体验。这是唯一真实的东西。</p><p>有意识的大脑每秒能<em>处理</em>50比特的信息。</p><p>无意识的大脑每秒能<em>管理</em>1100万比特的信息。</p><p>因此，如果我们想丰富日常体验，注意到更多新奇的机遇，实现不可能的事，并在生活中创造更多心流，我们必须扩展自我，方法是从根本上改变我们大脑用来驾驭现实所依据的目标。<strong>我们必须去影响由哪些信息来占据我们在任何一秒钟里的那50比特的处理能力。</strong></p><p>那么，什么是自我发展？</p><p>它就是增加你自我（或身份）的复杂性。</p><p>当你追求一个具有挑战性的目标时，你的头脑必须扩展到一个新层次，以获取解决实现该目标道路上的问题所需的知识和技能。</p><p>当你实现了一个目标，只有这时你才具备了实现下一个目标的觉察力和技能。</p><p>随着你实现那些不那么肤浅的目标，你就会达到一个可以去承担更有意义的机会的水平——那些你以前根本不知道其存在的机会。</p><p><strong>为了强调这一点：</strong></p><p>你不知道自己想要什么，因为除了别人吩咐你去做的事情之外，你的人生还没有做过任何别的事情。</p><p>你一直呆在人生这款电子游戏地图的“已知”区域。你没有接受一条罕见的任务线去深入未知领域，去挑战你的自我和能力。</p><p>但这不全怪你。</p><p>我们都在与一个敌人战斗，它导致了我们的压力、焦虑和崩溃感，其程度远超我们愿意承认的范围。</p><p>那个敌人叫做熵。</p><h2 id="意识中的混乱——为什么你的生活感觉失去了控制" tabindex="-1">意识中的混乱——为什么你的生活感觉失去了控制 <a class="header-anchor" href="#意识中的混乱——为什么你的生活感觉失去了控制" aria-label="Permalink to &quot;意识中的混乱——为什么你的生活感觉失去了控制&quot;">​</a></h2><blockquote><p>如果你理解了熵，你就会明白，如果在生活中什么都不做，你就是在选择慢慢溺水于混乱之中。你不会保持原样。你不费吹灰之力就会让自己越陷越深。美好的生活需要为了你自己的目标不断努力。</p></blockquote><p>让我们用一句话来总结目前为止学到的东西：</p><p><em>当你的意识内容由一项极具挑战但又有意义的任务构成时，心流状态就会发生。</em></p><p>但这里有一个问题。</p><p>大多数人感觉自己淹没在一团混乱之中。</p><p>占据他们注意力的不是一件有意义的任务，而是10个负面想法，且这10个想法有可能分裂成100个更多。就像你感到胸口一阵疼痛，脑海中就会浮现出爷爷心脏病发作的情景，你忽略了食用的10种有益心脏健康的食物，以及早逝可能会如何影响你的家人。</p><p><img src="'+i+'" alt=""></p><p>我想让你把自己的大脑想象成一台超级计算机。</p><p>你处理信息的能力取决于几个因素，但RAM——或随机存取存储器（内存）——是影响计算机性能的最重要部分。</p><p>运行的不同程序、打开的浏览器标签页，以及你所运行内容的性能要求占用的RAM越多，你的性能就会越慢。</p><p>这与你的大脑没什么两样。</p><p>你的显意识注意力所关注的东西至关重要。</p><p>大多数人的生活中都同时运行着多个高负荷程序，这些程序正在耗尽他们有限的创造力能量。</p><ul><li>关于过去遗憾错误的思考</li><li>关于未来充满压力事件的想法</li><li>为了逃避这些想法而产生的对饥饿感和娱乐的渴望</li><li>打破这种条件反射般生活方式的内心呐喊</li><li>一长串需要完成、优先级混乱的任务</li><li>那些本该完成却忘了做的任务所形成的未闭合循环</li></ul><p>这个清单还可以一直列下去。</p><p>现代人的大脑默认把注意力分散到无数个方向。我们在压力中度过每一天，近乎病态。我们没有全神贯注、心无旁骛地活在当下，而是恰恰相反——活在一个由注意力分散制造的虚假现实中。</p><p>当我们过多地思考零散的过去或未来时，混乱就会随之而来。大脑倾向于无序。如果不加以控制，我们就会失去对生活的控制感，而这种控制感正是乐趣的源泉。</p><p>这就引出了一个问题：</p><p><strong>什么是意识状态？</strong></p><p>这是一个极其深刻的问题，但在谈到心流<em>状态</em>（flow state）时，理解它至关重要。既然我们在处理一个形而上学的问题，请保持开放的心态，提出问题，并接受这些问题可能需要时间来回答和理清的事实。</p><p>这里的经验教训是：</p><p><em>多问问题。你不会立刻得到答案，但你在大脑中播下了种子，去接收一个你通常无法得到的答案。这可能需要一天、一周或一个月……而对于那些真正重要的问题，可能需要十年。</em></p><p>现实是采取不同状态的意识。除了意识状态，别无他物。所有真实存在的都是<em>状态</em>。对意识状态的否认，本身也是出自于一种意识状态。</p><p>如果有帮助的话，你可以简单地把“意识状态”看作“心境状态（states of mind）”。在很大程度上，它们是同义词。</p><p>意识有更高和更低的状态，两者没有谁比谁“更好”……它们只是“存在着”，但更高的意识状态有时可能更令人向往，比如进入心流（flow）以进行深度工作（deep work）。</p><p><img src="'+r+'" alt=""></p><p>困倦、醉酒、亢奋、焦虑、做梦、有压力、无聊或不堪重负，都处在一个意识或无意识、开阔或狭隘的心境状态光谱上。</p><p>大卫·R·霍金斯（David R. Hawkins）绘制了一张意识层级（或称意识阶段）的图谱。</p><p>肯·威尔伯（Ken Wilber）经常谈到“状态（states）”和“阶段（stages）”之间的区别。</p><p>状态是流动且暂时的心境模式。你每天都在各种状态之间摇摆。你可以把这看作你的“日常体验”，从晚上的疲惫到早上的专注。</p><p>阶段（或层级），代表了你发展的基线。你仍然可能陷入更低的<em>状态</em>，但你会很快回到基线，并倾向于在你所处的发展阶段附近徘徊。</p><p><img src="'+a+'" alt=""></p><p>那么，是什么导致了这种混乱的心境状态，以至于让我们的生活看起来像是在分崩离析？</p><p>我们注定要继续受其折磨吗？</p><p>最重要的是，我们如何提升自己的基础意识层级，从而获得更多心流，过上更好的生活？</p><h3 id="精神熵——一场大规模的心理健康危机" tabindex="-1">精神熵——一场大规模的心理健康危机 <a class="header-anchor" href="#精神熵——一场大规模的心理健康危机" aria-label="Permalink to &quot;精神熵——一场大规模的心理健康危机&quot;">​</a></h3><p>我们正在经历一场心理健康危机。</p><p>我们缺乏创造维持心流的终生事业所必需的好奇心、热情、目标、自主权和精通感。</p><p><em>大多数人都存在精神失序（mental disorder）。</em></p><p>不是<em>某种</em>精神疾病（a mental disorder），而就是精神失序。</p><p>我说的不是那种可以被诊断并开具处方解决方案的疾病（尽管这种情况也呈上升趋势……主要是为了从这场流行病中牟利）。</p><p>当我说精神失序时，我指的是大脑中的无序状态。</p><p><strong>精神熵（Psychic entropy）。</strong></p><p>精神（Psychic） = 关乎心智的。</p><p>熵（Entropy） = 系统倾向于无序。</p><p>系统需要持续的能量才能繁荣运转。</p><p>系统是由连接在一起或协同工作的一组部件组成的复合整体，旨在达成目标。每个部分都以某种方式影响系统，并依赖于其他部分才能正常运作。例如，你的消化系统由胃和肠等器官组成，它们协同工作以帮助你消化食物。</p><p>就像你的生意由品牌、内容、产品和营销组成一样。<a href="https://mentalmonetization.com/" target="_blank" rel="noreferrer">如果你没有一个好产品</a>（它本身就是一个系统），你就赚不到钱。如果你在系统的其他部分忽视了能量的投入，同样，你也赚不到钱。</p><p>随着时间的推移，系统会变得越来越高效，除非你疏忽了对它们的维护。</p><p>为了描述系统中的<em>熵</em>：如果你的大脑是一个房间，而你没有投入<em>能量</em>去打扫那个房间（维持秩序），那么房间就会变脏。</p><p>一天不打扫还没什么。但过了一周呢？一个月呢？一年呢？</p><p>然后你妈就会开始唠叨你活在猪圈里。</p><p>难怪焦虑在我们的社会中如此猖獗。所有人大概都有一年没打扫过自己的房间了，而且谁又愿意投入那么多额外的能量去打扫呢？一天后打扫房间可比一年后打扫容易多了。焦虑的循环不断持续，因为我们<em>知道</em>我们需要打扫房间，但我们就是不做。在想法和行动之间存在着一条鸿沟。</p><p>因此，如果你是一名作家，你需要花费一些时间和进行实验，才能养成习惯并建立系统，从而获得<a href="https://2hourwriter.com/" target="_blank" rel="noreferrer">受众和收入</a>。但一旦你掌握了，你就不需要投入那么多能量来维持它的运转。然而，如果你停了一天、一周或一个月，想要恢复原状就会变得越来越困难。</p><p>这正是问题发生的地方。</p><p>当作为我们大脑的这个系统出现能量堵塞时。</p><p>心理健康关乎<em>理清头绪、理解和保持清晰。</em></p><p>如果你让一种强迫性的负面想法劫持了某个情境，你就无法看清该情境的本来面目。</p><p>你会陷入自己的脑海中，满脑子想的都是<em>可能</em>发生的坏事。你把那种负面体验拽进了当下，然后它便开始影响你的思想和行动。</p><p>注意力为它触及的一切注入生命。</p><p>当你把注意力集中在大脑制造的虚假现实上时，你的行为方式就会让它<em>弄假成真。</em></p><p><em>你觉得在任何情况下，这会带来有益的结果吗？</em></p><p>解决混乱的终极方案，就是掌控你的人生。</p><h3 id="逆转熵——把能量投入到正确的目标上" tabindex="-1">逆转熵——把能量投入到正确的目标上 <a class="header-anchor" href="#逆转熵——把能量投入到正确的目标上" aria-label="Permalink to &quot;逆转熵——把能量投入到正确的目标上&quot;">​</a></h3><p><a href="https://thedankoe.com/letters/the-flow-state-turn-life-into-an-addictive-video-game/" target="_blank" rel="noreferrer">原站图片暂不可用，查看原文</a></p><p>在电子游戏中，你的思维是被游戏本身所框定的。</p><p>在现实中，这就是你的视角。我们之前讨论过。</p><p>为了进一步收束你的心智，有一套充满挑战的目标层级。</p><p>最后，为了让你沉浸在这个世界中，并将注意力集中在当下，还有各种规则和机制。</p><p>规则防止你作弊。它们让这个游戏值得一玩。</p><p>机制是基于技能的。一开始你的瞄准会很烂。操作键盘时你会觉得很笨拙。你无法灵活移动或准确命中。但是……你会变得更好。随着挑战的增加，你会不断练习并取得进步。</p><p>在生活中，规则就是你认为重要和有意义的东西。你的优先级。你的价值观。你所<em>珍视的</em>东西。</p><p>机制就是你用来实现生活中优先目标的技能和习惯。</p><p>要创造一种充满乐趣和心流的生活，你需要：</p><ul><li>把心智能量投入到自我生成的目标中</li><li>坚持足够长的时间来<em>创造</em>热情（热情不是光靠“找到”的）</li><li>建立供你的大脑运作的新系统（或日常惯例）</li></ul><p>这就是你逆转精神熵和大脑混乱的方法。</p><p>你<em>每一天都要通过思想、情绪、注意力和行动，将能量投入到那些通过工作、学习和实践来创造你理想生活的目标中。</em></p><p>值得庆幸的是，真正有意义的目标只有少数几个。</p><p>它们对应着那些无法被AI、处方药或技术解决的永恒难题：</p><ul><li><strong>事业</strong>——有意义的工作，能让你自主选择要去解决的问题。</li><li><strong>健康</strong>——你住在自己的身体里，了解并改善它是你的义务。</li><li><strong>心智</strong>——追随你的好奇心，获取知识，并扩展你的自我意识。</li><li><strong>联结</strong>——创造共享体验并扩大你的关注圈以超越自我（就像你在电子游戏中组队一样，多个大脑达成目标的速度比一个快）。</li></ul><p>就像电子游戏里的技能树一样。</p><p><a href="https://thedankoe.com/letters/the-flow-state-turn-life-into-an-addictive-video-game/" target="_blank" rel="noreferrer">原站图片暂不可用，查看原文</a></p><p>当你提升这些领域中的相关技能时，你就会解锁新的等级。</p><p>但这里有个前提：</p><p>你对一项特质的提升程度，只能与你对另一项特质的提升程度相当。</p><p>只有在创造性工作中达到某种水平，你才能在心智上达到相应的境界。</p><p>只有在心智上达到某种境界，你才能在健康上达到相应的水平（因为心理和生理健康是深度交织的）。</p><p><strong>我问你的问题是：</strong></p><p>如果你没有每天都在建设自己的心智、身体、事业和精神——那你到底在干嘛？</p><p>真心发问。</p><p>还有什么比这更重要的吗？</p><p>还是说你现在所做的一切都只是在分心？</p><p>“但是Dan，我想享受人生，做我自己想做的事。”</p><p><em>与快感相比，你明白什么是真正的乐趣吗？</em></p><p>你有没有意识到，在进化的过程中人类心理已经被勾勒出来，这表明人类天生就有一种去成长、去扩展、去超越和去创造的内在驱动力？</p><p>乐趣存在于进步之中。</p><p>心流状态所指向的，远不止是你大脑里的一些神经化学物质。</p><p>它指向的是神性。</p><p>“做你想做的事”通常是自我（ego）用来阻断那种能让你提升自己的思路的借口，因为那才是你本性真正渴望的：</p><p><em>做你想做的事，但要与你的目标保持一致。</em></p><p><em>追随好奇心。自我教育。建立有意义的项目，以此来实现你的理想生活方式。</em></p><p>不知道从哪开始？</p><p>算你走运。这正是我们接下来的议程。</p><h2 id="创造你自己的无限游戏——心流的神经科学" tabindex="-1">创造你自己的无限游戏——心流的神经科学 <a class="header-anchor" href="#创造你自己的无限游戏——心流的神经科学" aria-label="Permalink to &quot;创造你自己的无限游戏——心流的神经科学&quot;">​</a></h2><p>好了，我们已经明白了目标。</p><p>我们想创造一种拥有更多心流的生活。</p><p>我们想要对我们有意义的工作。</p><p>我们想要创造这样一种生活：对生活的结果拥有压倒性的掌控感。</p><p>我们<em>不想</em>被分配目标，并因此被分配一种身份和命运，沦为机器中的一个齿轮。</p><p>《不可能的艺术》（<em>The Art Of Impossible</em>）的作者史蒂芬·科特勒（Steven Kotler）认为，实现心流状态是有公式可循的，从而（如果使用得当的话）实现不可能的目标。</p><p>对齐动机是做好这一步的首要环节。他描述了5个内在驱动力，它们能为我们的行动提供燃料和能量：</p><ul><li><strong>好奇心</strong> – 我们探索未知的指南针。</li><li><strong>激情</strong> – 找到那件让你欲罢不能的事。</li><li><strong>目标</strong> – 你的激情将如何影响世界——某种超越你自身的东西。</li><li><strong>自主性</strong> – 追求激情和目标所必需的对自由的渴望。</li><li><strong>精通</strong> – 磨炼你的技能，从而将激情变现。</li></ul><p>根据科特勒的说法，这些驱动力中的每一个都会促生特定的神经递质，比如多巴胺、催产素、内啡肽、血清素和去甲肾上腺素。这种神经化学鸡尾酒有助于创造心流状态。</p><p>我鼓励你去读读他的书，去发现他达到心流的过程，但我有我自己的方法。</p><p>在我看来，这件事最好自上而下地去解决。</p><p><strong>精通</strong>源于你一生的事业。你对未来的愿景。</p><p><strong>自主性</strong>源于创业。创造你自己工作的能力。</p><p><strong>目标</strong>源于那些转化为产品的项目。一种帮助人们解决问题并扩大你关注圈的方法。</p><p><strong>激情</strong>源于将点滴联系起来。找到你正在拼凑的拼图碎片。</p><p><strong>好奇心</strong>是燃料。渴望获取知识以达到下一个层级的欲望。</p><p>以下是你需要做的：</p><h3 id="创造你的世界——痴迷的种子" tabindex="-1">创造你的世界——痴迷的种子 <a class="header-anchor" href="#创造你的世界——痴迷的种子" aria-label="Permalink to &quot;创造你的世界——痴迷的种子&quot;">​</a></h3><p><a href="https://thedankoe.com/letters/the-flow-state-turn-life-into-an-addictive-video-game/" target="_blank" rel="noreferrer">原站图片暂不可用，查看原文</a></p><p>正如我们之前了解到的，目标和问题构成了你的世界观。</p><p>因此，我们需要有意识地明确这些目标和问题。</p><p><strong>1) 创造一个反愿景</strong></p><p>我们的故事从一个反愿景开始。</p><p>你生命中的梦魇。</p><p>你将要培养的世界观的第一个极点。</p><p>一种促使你采取行动的积极恐惧机制。</p><p><em>你的反愿景就是你不想经历的未来。</em></p><p>开始持续记录那些你不想重复的经历。</p><ul><li>你不屑于学习的材料。</li><li>你不想去完成的工作。</li><li>你不希望卷入的争论。</li></ul><p>你无法在瞬间摆脱它们。</p><p>你的任务是将它们识别为需要解决的问题。</p><p>随着你的清单不断增加，确保你尽一切努力朝着相反的方向行动。</p><p><strong>2) 培养一个愿景</strong></p><p>如果你没有愿景，你就会迷失。</p><p>你无法创造结果，所以你注定只能机械地生活在既定结果之中。</p><p>你在生活的任何领域做出的每一个决定，都必须经过你愿景的过滤。</p><p>只有这样，你才能为你的行动赋予意义，并把干扰降到最低。</p><p>准确写下你渴望从生活中得到什么。</p><p><em>不要漏掉任何细节，但要意识到这是一个迭代的过程。</em></p><p>你第一次写出来的绝不会完全正确，而且可能永远也不会。这不是重点。花30分钟生成一个最小可行愿景。经常回来回顾它，对其进行增添、删减和改进，因为你的欲望不可避免地会随着你的失败而改变。</p><p><strong>3) 设定大目标与小目标</strong></p><p>大目标是为了指明方向。小目标是为了提供清晰度。两者都不是为了行动。</p><p>当摆在你面前的任务简单到你忍不住要去完成它时，你是不需要动力的。</p><p>把你的愿景分解成按十年、年、月、周和日计算的目标。</p><p>它们是你的向导，而不是你的主人。</p><p><em>对愿景要固执，对细节要灵活。</em></p><p>你的目标会随着你的改变而改变，接受这一点。</p><p>每天提醒自己你的反愿景、愿景和目标。</p><p>这就是你自己的小世界。</p><p>当你满脑子想的都是你的世界时，你的大脑就会密谋为你提供帮助。你会注意到别人注意不到的小细节。这给了你一种优势。它将多巴胺喷射到你的大脑中作为动力。它为更多的心流设定了场景。你不再担心那些你无法控制的问题。</p><p>远离社会的抓马（戏剧性事件）。</p><p><em>“那非洲挨饿的孩子们怎么办？”</em></p><p><em>“那下一次选举呢？”</em></p><p><em>“那个名人的撕逼大战怎么说？”（那都是为了赚钱并让你保持愚蠢而捏造出来的）。</em></p><p>到底什么才能真正解决这个问题？</p><p>是你为之哭泣并更换你的头像吗？</p><p>还是你尽可能地成为一个最全面发展的人类。</p><p>建立一份充满激情的、有能力帮助更多人的事业。</p><p>成为一个巨大的价值创造者，赋予他人知识和工具去<em>对此采取实际行动。</em></p><p>把你的痴迷传递给他人，让你的能量像野火一样蔓延，培养出几十到几千个更全面发展的个体，让他们齐心协力真正在社会中做出改变。</p><p><a href="https://thedankoe.com/letters/the-flow-state-turn-life-into-an-addictive-video-game/" target="_blank" rel="noreferrer">原站图片暂不可用，查看原文</a></p><p>当人们问你对[此处插入本周最热门的抓马事件]有什么看法时，你唯一的回答应该是“我不在乎”。</p><p>否则你就是一个NPC（非玩家角色）。</p><h3 id="成为一名创业者——你通往未知的道路" tabindex="-1">成为一名创业者——你通往未知的道路 <a class="header-anchor" href="#成为一名创业者——你通往未知的道路" aria-label="Permalink to &quot;成为一名创业者——你通往未知的道路&quot;">​</a></h3><p>如果你的愿景宏大、大胆且真正具有影响力，为别人打工是永远无法实现的。</p><p>史蒂芬·科特勒反复强调，一个MTP，即<em>宏大变革目标</em>（Massively Transformative Purpose），是实现人生中不可能之事的关键。</p><p>罗伯特·格林（Robert Greene）则布道般地讲述发现你的<em>人生任务。</em></p><p>在我看来，创业是长期主义者唯一符合逻辑的选择。</p><p><em>创业是一种心态，而不是一个头衔。</em></p><p>一种致力于解决无穷无尽的创造性问题的心态。一种防止陷入别人分派给你的重复日常的方法——因为这是一个会在你生活的其他领域引发另外10个问题的问题，而一个创业者会识别并解决它。</p><p><em>这是一场无限游戏，而不是有限游戏。</em></p><p><em>你的工作在不断进化，而不会停滞不前（除非你默许，但即便如此，至少这也是你的选择）。</em></p><p>如果你在朝九晚五的工作中待得太久，你就会变成办公隔间里的猴子。</p><p>你的心智天生就是为狩猎而生。</p><p>狩猎就是做出有助于你生存的新奇发现。</p><p>想象一下我们的祖先每天经过一丛光秃秃的灌木。这无益于他们的未来。</p><p>但有一天，它长出了新的浆果。</p><p>有人经过它，注意到了它，这种新奇事物引起了兴奋。他们要么把浆果采下来，要么记在心里留到以后再采，这样他们就能活得更久。</p><p>当你被困在一份你讨厌的工作中时，你生活在永恒的已知之中。你无法在已知中做出新发现。这是一个比大多数浮于表面生活的人所认为的更大的问题。对他们来说这很正常，所以他们根本没把这当成一个问题。</p><p>你会感到无聊、沮丧，觉得生活毫无意义，因为你唯一能获得的多巴胺来自于表层的来源。</p><p>你从不冒险，从不涉足未知领域，从不发现能提高大脑多巴胺水平的新知识、新工具和新潜能。</p><p>你必须进化。</p><p>创业就是充满不确定性的道路。</p><p>就像是在丛林中披荆斩棘。</p><p>它要求你去学习那些学校里不教的技能。</p><p>它要求你能够坦然接受失败、拒绝和缓慢的进展。</p><p>它要求你从错误中学习，明天重装上阵，不断推进，直到挖到金子。</p><p>作为一名创业者，你为了生存而“狩猎”的方式是：收集知识，创造有价值的产品，并把它呈现在能从中获益的人面前。</p><p>正如我探讨过的，我做这件事的路径是：</p><ul><li>建立个人品牌作为基础</li><li>在现实世界中解决你自己的问题（健康、财富、人际关系）</li><li>通过写作分发你的发现、观点和信念</li><li>从自由职业或辅导服务做起，并取得成果</li><li>销售投入时间较少的实体或数字产品（一旦你的受众增长起来）</li><li>通过坚持和迭代，在2-4年内获得丰厚的收入</li><li>扩大你对未来的愿景，并为了实现它去构建任何你想要的东西（软件、宇宙飞船，随便什么都行）</li></ul><p>这就是一人企业（one-person business）的商业模式。</p><p>你不需要建立一家估值十亿美元的公司。</p><p>你需要通过传授你学到的经验教训来吸引受众。</p><p>你需要通过构建产品来实现受众变现</p><p>多亏了互联网，这两件事的成本都是零。</p><p>如果你不知道从哪里开始，<a href="https://theone-personbusiness.com/" target="_blank" rel="noreferrer">免费下载我的一人企业迷你课程。</a></p><h3 id="把你的目标变成科学项目——学习与构建" tabindex="-1">把你的目标变成科学项目——学习与构建 <a class="header-anchor" href="#把你的目标变成科学项目——学习与构建" aria-label="Permalink to &quot;把你的目标变成科学项目——学习与构建&quot;">​</a></h3><p><a href="https://thedankoe.com/letters/the-flow-state-turn-life-into-an-addictive-video-game/" target="_blank" rel="noreferrer">原站图片暂不可用，查看原文</a></p><p>当你学会了如何学习，你就能在6个月内取得原本需要6年才能实现的成果。</p><p>让我们将上面学到的所有内容，通过实际步骤落地。</p><p><strong>1) 创造一个清晰度催化剂</strong></p><p>在我的生命中有几个时刻，我在认知和进度上取得了巨大的飞跃：</p><ul><li>写我的书</li><li>构建我的产品</li><li>写这些邮件通讯</li></ul><p>它们都有什么共同点？</p><p>我把它们当成一个项目来对待。</p><p>一个项目拥有：</p><ul><li>确定其规模的范围——范围越大越有利于发挥创造力。</li><li>一个大纲，这样你就可以记下日常生活中产生的灵感来填充这个大纲。</li><li>里程碑，让你对下一步的行动有明确的方向和清晰度。</li><li>一个现实世界的最后期限，迫使你采取行动，否则你的生存就会受到打击。</li><li>实验、试错，这样你就能把失败转化为教训。</li></ul><p>这篇邮件通讯有8600字。好几个星期以来我满脑子想的都是它，直到这篇视频散文（video essay）完成并发布到YouTube上之前，它将一直占据我的思绪。</p><p>这为心流状态提供了一个完美的环境。</p><p>这里有激发新奇感和多巴胺的模式识别，有来自里程碑的清晰度，有来自最后期限的挑战，还有为了学习而进行的实验。</p><p>确定你想学什么。</p><p>创建一个现实世界中的项目，并将其发布出来让别人看到。</p><p>如果你不知道要创建什么项目，看看别人是怎么做的。</p><p>如果你想学Photoshop，你的项目可以是任何东西，从一张图形到一个数字艺术场景。</p><p>如果你想学习如何健身，你的项目就是你的身体、营养方案和训练计划。</p><p>你的项目大纲不必完美。它最初可以只是一堆杂乱的想法清单，列出你认为自己必须去做和学习的事情。</p><p>项目就是一个体验的锚点。</p><p>你现在有地方可以写下你要尝试的想法、知识和技巧了。</p><p>当我写书的时候，我书的大纲让生活变得有意义。我遇到的几乎每一个想法都可以补充到大纲里。</p><p>我觉得自己又变回了孩子。我变得痴迷起来。</p><p>所有事物都在一个全新的视角下被重新审视。那就是我的项目视角。</p><p><strong>2) 边构建边学习</strong></p><p>如果你没有在构建，你就没有在学习。</p><p>如果你不把你学到的东西主动应用到你脑海中盘旋的问题上，你只是在堆砌无用的知识，最终沦为很快被遗忘的大脑迷雾。</p><p>当你<em>开始</em>构建某样东西时，你需要知道的事情只有那么几件：基础知识。</p><p>你现在完全没必要去研究什么高级战术。</p><p>基础知识能让你走完95%的路（对大多数人来说，这意味着数百万美元的财富、健硕的体格，或是毫无压力的生活）。大多数人只是分心了。</p><p>新战术也许能帮你带来5%的边际提升，但这部分心智带宽应该留给痴迷、精通，以及与少数几个特定技能和兴趣相关的终生事业。</p><p>当你有一个项目要构建时，请照做以下几点：</p><ul><li>购买该主题的入门级课程</li><li>在YouTube上观看教授基础知识的概述视频</li></ul><p>深入学习它们，直到你清楚下一步该做什么。然后放手去做，当你遇到问题时：</p><ul><li>回头查阅课程或视频的相关部分</li><li>研究如何直接解决那个问题</li><li>观看别人<em>构建</em>与你相似项目的教程，看看他们是如何克服这些问题的</li></ul><p>学习就是解决问题，而不是尽可能多地囤积知识。</p><p><strong>3) 教你所学</strong></p><p>门徒效应（The protégé effect）：</p><p>一种心理学现象，即通过教授、假装教授或准备向他人教授信息，能帮助个人更好地学习该信息。</p><p>当你教学时，你在学习过程中会更加专注，并能识别出帮助你学得更快的知识盲区。</p><p>当然，我建议通过以个人品牌（或你的公开简历）的名义写作来公开教学，这样你在学习的同时还能吸引高薪机会。（这也是我在<a href="https://2hourwriter.com/" target="_blank" rel="noreferrer">2小时写手</a>中教授的内容）。</p><ul><li>公开写作并任由他人批评。</li><li>教你的朋友，从而促成有趣的对话。</li></ul><p>教学几乎是在强迫你理顺信息。</p><p>你必须去构建它、解释它，并确保你传授的不是错误知识。</p><p>当我写这些新闻信时，我并非无所不知。但我可以保证，这4年的写作极大地加速了我在热爱领域内的学习，远超我被困在“教程地狱”里所能学到的。</p><p>当你建立一个品牌（不是在商业意义上，而是指你向世界展示的外在形象）时，构建和教学会融为一体，成为你的工作。</p><p>你的生活变成了一系列有意义的活动：解决问题、学习如何解决问题、教导他人，并以此获得收入。我相信这就是进化所赋予的可能：多亏了互联网，人们可以毫无障碍地做自己热爱的事情。</p><p><strong>4) 跃迁至新的心智境界</strong></p><p><em>阅读以扩展心智。</em></p><p><em>写作以组织心智。</em></p><p><em>构建以聚焦心智。</em></p><p>到这个阶段，你可能仍感到力不从心，或是觉得自己没学到多少东西。</p><p>这是一件好事。</p><p>你的大脑已准备好进行模式识别。</p><p>所以：</p><ul><li><strong>将自己投身未知</strong> —— 将自己沉浸在与你试图学习的知识相关的文化、环境和信息中。</li><li><strong>通过重复和接触来训练心智</strong> —— 慢慢理解那些在该领域取得成功的人的行话、词汇和技能包。</li><li><strong>让心智在不适中扩展</strong> —— 你能做的最糟糕的事，就是在感受到成长的阵痛时选择放弃。</li></ul><p>你没有看到结果，因为你还不是那个配得上看到结果的人。</p><p>这个过程能让旧版本的你死去，从而让你蜕变成一个全新的人。</p><p>就像你在培养新习惯时，你必须摆脱那个助长你坏习惯的旧环境。</p><p>为了让这更具操作性：</p><ul><li><strong>读书</strong> —— 书本能让你通过6小时的阅读获得别人10年的心血。</li><li><strong>消化讲座</strong> —— 长文章和视频能让你在20分钟内汲取别人3天的努力。</li><li><strong>关注新人</strong> —— 这与其说是为了消费短篇幅内容，不如说是为了训练你的大脑融入那个特定的人群部落。</li></ul><p>买3本书。</p><p>一本畅销书，一本技术类书籍，一本历史类书籍。</p><p>一口气读完它们，不要让你的痴迷熄灭。</p><p>这似乎是一个漫长的过程，但我们并非要停留在表面学习，我们试图以最快的速度成为大师。</p><p><strong>5) 建立联系以巩固理解</strong></p><p>当你精通了一件事，精通其他事情就会变得更容易。</p><p>原理是普适的。它们相互重叠。</p><p>当你精通了健身，你就能用一半的时间精通商业，再用剩下的一半时间精通人际关系。</p><p>大多数人一生中从未精通哪怕一个领域，因此他们从未体验过指数级的个人成长。</p><p>当你觉得对自己正在学习的主题有了扎实的理解时：</p><ul><li>拉远一个层次 —— 从“Photoshop”升级到“平面设计”，再到“创意工作”。</li><li>留意信号 —— 当你的大脑发出重要信息的信号时，把它写下来。</li><li>构建更好的项目 —— 从一个全新的心智境界，构建一个能带你走向你所渴望的成功的新项目。</li></ul><p>根据我个人的经验，当我剥开表层，从网页设计走向营销，再到内容创作，最后触及形而上学时，我的知识产生了复利效应。</p><p>这也是开启你的一人企业的绝佳方式。</p><p>从在一个领域中学习、教学和构建开始，然后随着你的受众扩大而向外拓展。</p><h2 id="结语" tabindex="-1">结语 <a class="header-anchor" href="#结语" aria-label="Permalink to &quot;结语&quot;">​</a></h2><p>这是一封异常长的信。</p><p>我不想遗漏任何要点。</p><p>但说实话，关于这个话题，我完全可以写出一整本书。</p><p>事实上，我已经写了，书名就叫<a href="https://theartoffocusbook.com/" target="_blank" rel="noreferrer">《专注的艺术》（The Art Of Focus）</a>。</p><p>我希望你现在能够意识到，像心流这样的一种意识状态，是与整个生活相连的。它不仅关乎神经科学，更集形而上学、心理学、自我提升和生产力于一身。</p><p>它为我们如何过上美好生活提供了令人难以置信的启示。</p><p>如果你已经读到了这里，不妨考虑把这篇文章分享给你的朋友。</p><p>这或许正是他们此刻所需要的。</p><p>如果你想了解我是如何撰写这些文章、运营我的企业，或者将我毕生事业变现的——欢迎查看我网站上提供的免费和付费工具。</p><p>感谢阅读。</p><p>下次见：</p><p>—— 丹 (Dan)</p><hr><p><a href="/en/letters/the-flow-state-turn-life-into-an-addictive-video-game">查看英文存档</a> · <a href="/letters/">返回全部文章</a></p>',466))])}const T=o(c,[["render",g]]);export{P as __pageData,T as default};
